auto* location = toolbar ? toolbar->location_bar_view() : nullptr;
if (!location || !location->omnibox_view()) return false;
if (GetKind(browser) == Kind::kQuick) {
  // Chromium popup location bars are read-only by default. A registered
  // Quick window is a small browser and keeps the actual omnibox editor.
  auto* omnibox = location->omnibox_view();
  omnibox->SetReadOnly(false);
  omnibox->GetViewAccessibility().SetReadOnly(false);
  omnibox->GetViewAccessibility().SetIsEditable(true);
}
